import React, { useState } from "react";

export default function PostForm() {
  const [image, setImage] = useState(null);
  const [imagePreview, setImagePreview] = useState(null);
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [hashtags, setHashtags] = useState("");

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    setImage(file);
    setImagePreview(URL.createObjectURL(file));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log({
      title,
      content,
      hashtags: hashtags.split(" ").filter((tag) => tag.startsWith("#")),
      image,
    });
    alert("Post submitted! (see console)");
  };

  return (
    <div className="flex flex-col lg:flex-row p-6 gap-6 max-w-7xl mx-auto">
      {/* Left side form */}
      <div className="flex-1 space-y-4">
        <h2 className="text-xl font-bold">make post</h2>

        {/* Image upload */}
        <div className="border p-4 rounded">
          <label className="block mb-2 font-medium">upload image (1/18)</label>
          {imagePreview ? (
            <img
              src={imagePreview}
              alt="preview"
              className="h-40 object-contain mb-2"
            />
          ) : (
            <div className="w-full h-40 border border-dashed flex items-center justify-center text-gray-400">
              No image
            </div>
          )}
          <input type="file" accept="image/*" onChange={handleImageChange} />
        </div>

        {/* Content */}
        <div>
          <input
            type="text"
            placeholder="填写标题会有更多赞哦~"
            className="w-full p-2 border rounded mb-2"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
          />
          <textarea
            placeholder="input text"
            className="w-full p-2 border rounded"
            rows={6}
            value={content}
            onChange={(e) => setContent(e.target.value)}
          />
        </div>

        {/* Hashtags */}
        <div>
          <label className="block font-medium mb-1"># 话题</label>
          <input
            type="text"
            placeholder="#小红书游学团 #宠物宅家文艺复兴"
            className="w-full p-2 border rounded"
            value={hashtags}
            onChange={(e) => setHashtags(e.target.value)}
          />
        </div>

        {/* Buttons */}
        <div className="flex gap-4 mt-4">
          <button
            onClick={handleSubmit}
            className="bg-red-500 text-white px-4 py-2 rounded"
          >
            发布
          </button>
          <button className="border px-4 py-2 rounded text-gray-600">
            暂存离开
          </button>
        </div>
      </div>

      {/* Right side: preview mock */}
      <div className="hidden lg:block w-80 border p-4 rounded shadow bg-white">
        <h3 className="text-lg font-semibold mb-2">手机预览</h3>
        <div className="w-full h-96 border border-dashed flex items-center justify-center text-gray-400">
          模拟预览区域
        </div>
      </div>
    </div>
  );
}
